// Headless verification harness for the floppy blueprint module.
// Runs the real geometry/animation code with stubbed DOM + WebGL renderer.
import fs from 'node:fs';

const html = fs.readFileSync('../index.html', 'utf8');
const match = html.match(/<script type="module">([\s\S]*?)<\/script>/);
if (!match) { console.error('FAIL: module script not found'); process.exit(1); }
let js = match[1];

// --- patch imports ---
js = js.replace(
  `import * as THREE from 'three';`,
  `import * as THREE from './lib/three.module.js';`
);
js = js.replace(`import { OrbitControls } from 'three/addons/controls/OrbitControls.js';\n`, '');
js = js.replace(`import { CSS2DRenderer, CSS2DObject } from 'three/addons/renderers/CSS2DRenderer.js';\n`, '');
js = js.replace(
  `import { CSS2DRenderer, CSS2DObject } from 'three/addons/renderers/CSS2DRenderer.js';`,
  ''
);

// --- patch WebGL renderer creation (no GPU in node) ---
const rendererBlock = /const renderer = new THREE\.WebGLRenderer\(\{[\s\S]*?renderer\.setSize\(innerWidth, innerHeight\);/;
if (!rendererBlock.test(js)) { console.error('FAIL: renderer block not found'); process.exit(1); }
js = js.replace(rendererBlock,
  `const renderer = { domElement: { addEventListener(){} }, setClearColor(){}, setPixelRatio(){}, setSize(){}, render(){} };`
);

// --- expose internals at the end ---
js = js.replace('animate();',
`animate();
globalThis.__hooks = {
  THREE, parts, labels, dashedLines, scene, camera,
  updateAnimation, triggerExplode, toggleExplode, applyPart,
  easeInOutCubic, setHintVisible, showLabels, hideLabels,
};`);

const preamble = `
// ---- minimal DOM / renderer stubs (headless) ----
const __clock = { now: 1000 };
const __makeEl = () => ({
  style: {}, className: '', textContent: '', width: 0, height: 0,
  classList: { toggle(){} },
  appendChild(){}, addEventListener(){},
  getContext(){ return { setTransform(){}, fillRect(){}, beginPath(){}, arc(){}, fill(){} }; },
});
globalThis.document = {
  getElementById(){ return __makeEl(); },
  createElement(){ return __makeEl(); },
};
globalThis.window = { addEventListener(){}, devicePixelRatio: 1 };
globalThis.innerWidth = 1440;
globalThis.innerHeight = 900;
globalThis.requestAnimationFrame = () => 0; // freeze render loop; we drive it manually
globalThis.performance = { now: () => __clock.now };
class OrbitControlsStub {
  constructor(camera, dom){ this.camera = camera; this.dom = dom;
    this.target = { set(){}, length(){ return 0; },
      clone(){ return { multiplyScalar(){ return { sub(){ return { clone(){ return {}; } }; } }; } }; },
      copy(){} }; }
  addEventListener(){} update(){}
}
class CSS2DObjectStub extends THREE.Object3D {}
class CSS2DRendererStub { constructor(){ this.domElement = { style: {} }; } setSize(){} render(){} }
const OrbitControls = OrbitControlsStub;
const CSS2DObject = CSS2DObjectStub;
const CSS2DRenderer = CSS2DRendererStub;
globalThis.__clock = __clock;
`;

fs.writeFileSync('tmp_test.mjs', preamble + js);

// now import and run checks
const h = (await import('./tmp_test.mjs?t=' + Date.now())).default ?? globalThis.__hooks;
// note: module sets globalThis.__hooks at end
const H = globalThis.__hooks;
if (!H) { console.error('FAIL: hooks not exported'); process.exit(1); }

let failures = 0;
function check(name, cond, extra = '') {
  if (cond) console.log(`  PASS  ${name}`);
  else { console.log(`  FAIL  ${name} ${extra}`); failures++; }
}
function close(a, b, eps = 1e-4) { return Math.abs(a - b) < eps; }

console.log('\n=== STATIC STRUCTURE ===');
check('8 animated parts', H.parts.length === 8, `got ${H.parts.length}`);
check('12 CSS2D labels', H.labels.length === 12, `got ${H.labels.length}`);
check('6 dashed lines (4 vertical + shutter + tab)', H.dashedLines.length === 6, `got ${H.dashedLines.length}`);

// assembled positions
const expAssembled = [[0,1.5,0],[0,1,0],[0,0.7,0],[0,0.5,0],[0,0,0],[0,-1.5,0],[-10,-1.5,-23],[25.5,-1,25.5]];
check('all parts start at assembledY', H.parts.every((p,i) =>
  close(p.group.position.x, expAssembled[i][0]) &&
  close(p.group.position.y, expAssembled[i][1]) &&
  close(p.group.position.z, expAssembled[i][2])
));

// initial opacities = 1 (assembled opaque)
check('initial fill opacities = 1', H.parts.every(p => p.mats.every(m => close(m.material.opacity, 1))));

console.log('\n=== SHELL / CHANNEL ALIGNMENT ===');
// head channel constants must be identical across top shell, bottom shell, shutter
// (extract channel rect from the module source as ground truth)
const CHAN = { x0: -20, x1: -14, z0: -30, z1: -16 };
// shutter assembled offset → window world rect must equal the channel rect
const shutter = H.parts[6];
const winLocal = { x0: -10, x1: -4, z0: -7, z1: 7 };
const wx0 = shutter.group.position.x + winLocal.x0;
const wx1 = shutter.group.position.x + winLocal.x1;
const wz0 = shutter.group.position.z + winLocal.z0;
const wz1 = shutter.group.position.z + winLocal.z1;
check('shutter window == channel rect (assembled)',
  close(wx0, CHAN.x0) && close(wx1, CHAN.x1) && close(wz0, CHAN.z0) && close(wz1, CHAN.z1),
  `window x[${wx0},${wx1}] z[${wz0},${wz1}] vs channel x[${CHAN.x0},${CHAN.x1}] z[${CHAN.z0},${CHAN.z1}]`);
// window short edge (6, along X) parallel to shutter long edge (22, along X):
check('window 6x14 ratio & bias-left', (wx1-wx0) === 6 && (wz1-wz0) === 14 && wx0 < shutter.group.position.x);

// shutter must be opaque: from==to==1
check('shutter stays opaque (from=to=1)', shutter.mats[0].from === 1 && shutter.mats[0].to === 1);
// disk target opacity 0.5
const disk = H.parts[3];
check('disk exploded target opacity 0.5', close(disk.mats[0].to, 0.5));
// ghost fills target 0.08
check('ghost fill target opacity 0.08', H.parts.every((p,i) => i !== 6 ? close(p.mats[0].to, 0.08) : true));

console.log('\n=== GEOMETRY CHECKS ===');
// traverse scene for meshes/lines
let meshes = 0, lineSegs = 0, lines = 0;
H.scene.traverse(o => {
  if (o.isMesh) meshes++;
  else if (o.isLineSegments) lineSegs++;
  else if (o.isLine) lines++;
});
check('scene has meshes', meshes > 20, `${meshes}`);
check('scene has edge line segments', lineSegs > 15, `${lineSegs}`);
check('scene has plain lines (arrows/reflections/leaders)', lines >= 9, `${lines}`);

// every mesh geometry must actually build + have non-empty edge output
let badGeo = 0;
H.scene.traverse(o => {
  if (o.isMesh && o.geometry && !o.geometry.attributes.position) badGeo++;
});
check('all mesh geometries have positions', badGeo === 0);

// vertices count sanity on shells (extruded bodies must be substantial)
let shellVerts = 0;
H.scene.traverse(o => {
  if (o.isMesh && o.geometry.type === 'ExtrudeGeometry') shellVerts += o.geometry.attributes.position.count;
});
check('extruded geometry present (shells/liners/hub/shutter)', shellVerts > 5000, `${shellVerts} verts`);

console.log('\n=== ANIMATION STATE MACHINE ===');
const clock = globalThis.__clock;
// state: assembled → explode
H.triggerExplode();
check('state = exploding', true); // (internal; verify via positions below)
// advance past explode duration + stagger
clock.now += 3000 + 560 + 200;
H.updateAnimation();
const expExploded = [[0,45,0],[0,30,0],[0,18,0],[0,15,0],[0,0,0],[0,-15,0],[-30,-15,-30],[34,-15,34]];
check('explode: all parts at exploded positions', H.parts.every((p,i) =>
  close(p.group.position.x, expExploded[i][0]) && close(p.group.position.y, expExploded[i][1]) && close(p.group.position.z, expExploded[i][2])));
check('explode: ghost fills at 0.08', H.parts.every(p => p.mats.every(m => close(m.material.opacity, 0.08))));
check('explode: disk at 0.5', close(disk.mats[0].material.opacity, 0.5));
check('explode: shutter stays 1.0', close(shutter.mats[0].material.opacity, 1.0));
// depthWrite should be false in ghost state
check('ghost depthWrite=false', H.parts.every(p => p.mats.every(m => m.material.depthWrite === false)));

// mid-animation stagger check: at t=+2000ms, top shell should be further along than bottom shell
H.toggleExplode(); // now in 'exploded' → collapse
// first collapse waits 350ms; advance 350+1000ms → mid-collapse
clock.now += 350 + 1000;
H.updateAnimation();
const yTop = H.parts[0].group.position.y;      // from 45 → 1.5
const yBot = H.parts[5].group.position.y;      // from -15 → -1.5 (delayed)
check('collapse: stagger respected (bottom shell lags)', yTop < 40 && yTop > 5 && yBot < -1, `yTop=${yTop.toFixed(1)} yBot=${yBot.toFixed(1)}`);
// complete the collapse
clock.now += 3000 + 560 + 200;
H.updateAnimation();
check('collapse: back to assembled positions', H.parts.every((p,i) =>
  close(p.group.position.x, expAssembled[i][0]) && close(p.group.position.y, expAssembled[i][1]) && close(p.group.position.z, expAssembled[i][2])));
check('collapse: opacities back to 1', H.parts.every(p => p.mats.every(m => close(m.material.opacity, 1))));
check('collapse: depthWrite back on', H.parts.every(p => p.mats.every(m => m.material.depthWrite === true)));

console.log('\n=== EASING ===');
check('easeInOutCubic(0)=0', close(H.easeInOutCubic(0), 0));
check('easeInOutCubic(0.5)=0.5', close(H.easeInOutCubic(0.5), 0.5));
check('easeInOutCubic(1)=1', close(H.easeInOutCubic(1), 1));

console.log(failures === 0 ? '\nALL CHECKS PASSED' : `\n${failures} CHECK(S) FAILED`);
process.exit(failures === 0 ? 0 : 1);

