// Project the real scene (exploded state) through the real ortho camera into an SVG.
import fs from 'node:fs';

// reuse the same patched module build as harness.mjs
const { buildPatched } = await import('./build.mjs');
const { H, clock } = buildPatched();

// drive to fully exploded + reveal labels/dashed lines
H.triggerExplode();
clock.now += 3000 + 560 + 200;
H.updateAnimation();
// force everything visible for the diagram
H.scene.traverse(o => {
  if (o.isLine) o.visible = true;
  if (o.material) o.material.opacity = 1;
});
H.labels.forEach(l => { l.div.style.opacity = '1'; l.leader.visible = true; });
H.dashedLines.forEach(l => { l.visible = true; l.material.opacity = 1; });

const cam = H.camera;
cam.updateMatrixWorld(true);
cam.updateProjectionMatrix();

const W = 1280, Hh = 820;
function project(v) {
  const p = v.clone().applyMatrix4(cam.matrixWorldInverse).applyMatrix4(cam.projectionMatrix);
  return [(p.x * 0.5 + 0.5) * W, (1 - (p.y * 0.5 + 0.5)) * Hh];
}
function ptsToSvg(arr) {
  return arr.map(([x, y]) => `${x.toFixed(1)},${y.toFixed(1)}`).join(' ');
}
function collectWorldPoints(obj, out) {
  if (obj.geometry && obj.geometry.attributes && obj.geometry.attributes.position) {
    const pos = obj.geometry.attributes.position;
    const tmp = new H.THREE.Vector3();
    for (let i = 0; i < pos.count; i++) {
      tmp.fromBufferAttribute(pos, i);
      out.push(tmp.clone().applyMatrix4(obj.matrixWorld));
    }
  }
  obj.children.forEach(c => collectWorldPoints(c, out));
}

let svg = `<svg xmlns="http://www.w3.org/2000/svg" width="${W}" height="${Hh}" viewBox="0 0 ${W} ${Hh}">
<rect width="100%" height="100%" fill="#F5F7FA"/>`;

// dot grid
for (let x = 20; x < W; x += 26) for (let y = 20; y < Hh; y += 26) {
  svg += `<circle cx="${x}" cy="${y}" r="1.2" fill="rgba(100,116,139,0.3)"/>`;
}

// edge lines / leader lines (stroke polyline through projected vertices)
function emitLine(obj) {
  const pts = [];
  const pos = obj.geometry.attributes.position;
  const tmp = new H.THREE.Vector3();
  const m = obj.matrixWorld;
  for (let i = 0; i < pos.count; i++) { tmp.fromBufferAttribute(pos, i); pts.push(project(tmp.applyMatrix4(m))); }
  const dashed = obj.isLine && obj.material && obj.material.isLineDashedMaterial;
  const dash = dashed ? ' stroke-dasharray="5,5"' : '';
  const width = dashed ? 1.2 : 0.8;
  svg += `<polyline fill="none" stroke="#4169E1" stroke-width="${width}"${dash} points="${ptsToSvg(pts)}"/>`;
}
H.scene.traverse(o => {
  if (o.isLine || o.isLineSegments) { if (o.geometry && o.geometry.attributes.position) emitLine(o); }
});

// label anchors
H.labels.forEach(l => {
  const p = project(l.leader.geometry.attributes.position.getX(1) !== undefined
    ? new H.THREE.Vector3().fromBufferAttribute(l.leader.geometry.attributes.position, 1)
    : new H.THREE.Vector3());
  // text at label position: use leader's 2nd point (label pos)
  const p1 = new H.THREE.Vector3().fromBufferAttribute(l.leader.geometry.attributes.position, 1);
  const pp = project(p1);
  svg += `<text x="${pp[0] + 6}" y="${pp[1] + 4}" font-family="Courier New" font-size="11" fill="#4169E1">${l.div.textContent}</text>`;
});

svg += '</svg>';
fs.writeFileSync('blueprint.svg', svg);
console.log('SVG written, lines done.');

// Shared builder: patches index.html's module script, imports it in Node,
// and returns the exposed hooks + fake clock.
import fs from 'node:fs';

export async function buildPatched() {
  const html = fs.readFileSync('../index.html', 'utf8');
  const match = html.match(/<script type="module">([\s\S]*?)<\/script>/);
  if (!match) throw new Error('module script not found');
  let js = match[1];

  js = js.replace(`import * as THREE from 'three';`, `import * as THREE from './lib/three.module.js';`);
  js = js.replace(`import { OrbitControls } from 'three/addons/controls/OrbitControls.js';\n`, '');
  js = js.replace(`import { CSS2DRenderer, CSS2DObject } from 'three/addons/renderers/CSS2DRenderer.js';\n`, '');

  const rendererBlock = /const renderer = new THREE\.WebGLRenderer\(\{[\s\S]*?renderer\.setSize\(innerWidth, innerHeight\);/;
  js = js.replace(rendererBlock,
    `const renderer = { domElement: { addEventListener(){} }, setClearColor(){}, setPixelRatio(){}, setSize(){}, render(){} };`);

  js = js.replace('animate();',
    `animate();
globalThis.__hooks = {
  THREE, parts, labels, dashedLines, scene, camera,
  updateAnimation, triggerExplode, toggleExplode, applyPart,
  easeInOutCubic, setHintVisible, showLabels, hideLabels,
};`);

  const preamble = `
const __clock = { now: 1000 };
const __makeEl = () => ({
  style: {}, className: '', textContent: '', width: 0, height: 0,
