// Numeric checks on the projected exploded view (screen-space sanity).
const { buildPatched } = await import('./build.mjs');
const { H, clock } = await buildPatched();

H.triggerExplode();
clock.now += 3000 + 560 + 200;
H.updateAnimation();
H.scene.traverse(o => { if (o.isLine) o.visible = true; if (o.material) o.material.opacity = 1; });

const cam = H.camera;
cam.updateMatrixWorld(true);
cam.updateProjectionMatrix();
const W = 1280, HH = 820;
const proj = (v) => {
  const p = v.clone().applyMatrix4(cam.matrixWorldInverse).applyMatrix4(cam.projectionMatrix);
  return [(p.x * 0.5 + 0.5) * W, (1 - (p.y * 0.5 + 0.5)) * HH];
};

let failures = 0;
const check = (n, c, e = '') => { console.log((c ? '  PASS  ' : '  FAIL  ') + n + (c ? '' : '  ' + e)); if (!c) failures++; };

// 1) all projected edge vertices inside viewport (with small margin)
let minX = 1e9, maxX = -1e9, minY = 1e9, maxY = -1e9, out = 0;
H.scene.traverse(o => {
  if ((o.isLine || o.isLineSegments) && o.geometry && o.geometry.attributes.position) {
    const pos = o.geometry.attributes.position; const v = new H.THREE.Vector3();
    for (let i = 0; i < pos.count; i++) {
      v.fromBufferAttribute(pos, i); const [x, y] = proj(v.applyMatrix4(o.matrixWorld));
      minX = Math.min(minX, x); maxX = Math.max(maxX, x);
      minY = Math.min(minY, y); maxY = Math.max(maxY, y);
      if (x < 5 || x > W - 5 || y < 5 || y > HH - 5) out++;
    }
  }
});
check('model projected within viewport', out === 0, `${out} verts outside`);
check('model occupies a sensible region', maxX - minX > 500 && maxY - minY > 300,
  `bbox x[${minX.toFixed(0)},${maxX.toFixed(0)}] y[${minY.toFixed(0)},${maxY.toFixed(0)}]`);

// 2) screen-space layering: top shell above bottom shell, exploded gap readable
const pTop = proj(H.parts[0].group.position.clone().setY(46));
const pBot = proj(H.parts[5].group.position.clone().setY(-14));
check('top shell above bottom shell on screen', pTop[1] < pBot[1],
  `top y=${pTop[1].toFixed(0)} bottom y=${pBot[1].toFixed(0)}`);

// 3) screen-space channel alignment: shutter window center vs shell channel center
const shC = proj(H.parts[6].group.position.clone());            // shutter plate center (exploded)
const chC = proj(new H.THREE.Vector3(-17, -15, -23));           // channel center at shell level
check('shutter sits left-front of bottom shell on screen', shC[0] < chC[0] - 40, `dx=${(chC[0]-shC[0]).toFixed(0)}`);

// 4) labels within viewport
let labelsOut = 0;
H.labels.forEach(l => {
  const pos = new H.THREE.Vector3().fromBufferAttribute(l.leader.geometry.attributes.position, 1);
  const [x, y] = proj(pos);
  if (x < 20 || x > W - 20 || y < 20 || y > HH - 20) labelsOut++;
});
check('all 12 label anchors within viewport', labelsOut === 0, `${labelsOut} out`);

// 5) dashed vertical lines span the shell stack (endpoint world Y)
const dashed = H.dashedLines.slice(0, 4);
check('vertical dashed lines span the exploded stack',
  dashed.every(l => l.geometry.attributes.position.getY(0) <= -18 && l.geometry.attributes.position.getY(1) >= 48));

console.log(failures === 0 ? '\nPROJECTION CHECKS PASSED' : `\n${failures} FAILED`);
process.exit(failures ? 1 : 0);

